def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # The line-shaped component is the paint-color indicator.
    def marker_rank(obj):
        cells = obj[1]
        ys = [y for y, x in cells]
        xs = [x for y, x in cells]
        dy, dx = max(ys) - min(ys) + 1, max(xs) - min(xs) + 1
        return max(dy, dx) / min(dy, dx), len(cells)

    marker = max(comps, key=marker_rank)
    mc, marker_cells = marker

    # Select the nearest non-marker object (distance between object cells).
    def gap(obj):
        return min(abs(y-a) + abs(x-b)
                   for y, x in obj[1] for a, b in marker_cells)

    candidates = [obj for obj in comps if obj[0] != mc]
    target = min(candidates, key=lambda obj: (gap(obj), -len(obj[1])))

    out = [row[:] for row in grid]
    for r, c in target[1]:
        out[r][c] = mc
    return out
